using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using HarborValeGreybox.Workshop;
using HarborValeGreybox.Driving;
namespace HarborValeGreybox.Racing.Editor {
public static class InventoryVerification {
 static readonly List<string> checks=new List<string>();static void Check(bool yes,string text){checks.Add((yes?"PASS ":"FAIL ")+text);if(!yes)throw new Exception(text);}static void Reject(Action a,string text){bool failed=false;try{a();}catch{failed=true;}Check(failed,text);}
 static TrialSession Finished(TrialDefinition d){var s=new TrialSession(d);s.Tick(4,Vector3.zero,Vector3.zero);s.Tick(90,Vector3.zero,Vector3.zero);foreach(var g in d.checkpoints)s.Tick(.02f,g.Position-g.Forward,g.Position+g.Forward);return s;}
 static DuelRaceSession Win(DuelContract d,TrialDefinition route){var s=new DuelRaceSession(d,route);s.Tick(4,Vector3.zero,Vector3.zero,Vector3.zero,Vector3.zero);foreach(var g in route.checkpoints)s.Tick(.02f,g.Position-g.Forward,g.Position+g.Forward,Vector3.zero,Vector3.zero);return s;}
 static void Parts(RaceProgressStore s,string part){var catalog=WorkshopCatalog.ForBuild(s.ActiveModelId,s.ActiveWorkshop);foreach(var o in catalog.MissingPath(s.ActiveWorkshop,catalog.Find(part)))s.PurchaseWorkshop(Guid.NewGuid().ToString("N"),o.id,catalog.Price(s.ActiveWorkshop,o),out _);}
 static string Buy(RaceProgressStore s,string model){var spec=VehicleLineup.Find(model);s.BuyVehicle(Guid.NewGuid().ToString("N"),model,spec.price);return s.Profile.fleet.selectedId;}
 public static void Run(){Directory.CreateDirectory("Verification/Inventory");try{LineupAssets.Build();Check(VehicleLineup.All.Length==4,"Four model-specific profiles include Blender Tempest hypercar");var route=JsonUtility.FromJson<TrialDefinition>(Resources.Load<TextAsset>("FirstDocksideTrial").text);string folder=Path.GetFullPath("Verification/Inventory/profiles/"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string file=folder+"/v9.json",old=Path.GetFullPath("Verification/Inventory/fixtures/released-v7.json"),bytes=File.ReadAllText(old);var before=JsonUtility.FromJson<RaceProgress>(bytes);var store=new RaceProgressStore(file,route,lineupLegacyFile:old);Check(store.Profile.version==9&&store.Profile.profileId==before.profileId&&store.Profile.availableCredits==before.availableCredits&&JsonUtility.ToJson(store.Profile.spending)==JsonUtility.ToJson(before.spending),"Released v7 migrates read-only to v9 preserving money/identity/receipt amounts");Check(store.Profile.fleet.engines.Count==store.Profile.fleet.cars.Count&&store.Profile.fleet.engines.All(e=>!string.IsNullOrEmpty(e.installedCarId)),"Migration registers each genuinely fitted engine once, with no invented stored kits");Check(File.ReadAllText(old)==bytes,"Old save remains byte-identical");for(int i=0;i<400;i++)store.Settle(Finished(route),out _);
  string coda=Buy(store,"car_coda"),bastion=Buy(store,"car_bastion");Parts(store,"induction_small_1");Parts(store,"cooling_1");string engine=FleetLedger.Find(store.Profile.fleet,bastion).engineId;int count=store.Profile.fleet.engines.Count;string donorPower=JsonUtility.ToJson(EngineInventoryLedger.Power(store.ActiveWorkshop));Reject(()=>store.EngineTransferFee(bastion,coda),"High donor torque requires receiver gearbox support before transplant");store.SelectVehicle(Guid.NewGuid().ToString("N"),coda);Parts(store,"gearbox_3");Parts(store,"brakes_2");Parts(store,"tires_2");var chassis=FleetLedger.Find(store.Profile.fleet,coda).build;int gear=chassis.gearboxStage,brakes=chassis.brakeStage,tires=chassis.tireStage;string displaced=FleetLedger.Find(store.Profile.fleet,coda).engineId;store.SelectVehicle(Guid.NewGuid().ToString("N"),bastion);string pull=Guid.NewGuid().ToString("N");store.PullEngine(pull,bastion);store.PullEngine(pull,bastion);Check(!store.HasEngine(bastion)&&EngineInventoryLedger.Find(store.Profile.fleet,engine).installedCarId==""&&store.Profile.fleet.engines.Count==count,"Pull and retry store same unique tuned assembly and leave donor engineless");Reject(()=>store.SelectVehicle(Guid.NewGuid().ToString("N"),bastion),"Engineless owned car cannot be selected for driving");Check(JsonUtility.ToJson(EngineInventoryLedger.Find(store.Profile.fleet,engine).build)==donorPower,"Removed assembly retains exact paid turbo/tune/cooler power state");int fee=store.EngineFitFee(engine,coda),cash=store.Profile.availableCredits;string fit=Guid.NewGuid().ToString("N");store.FitEngine(fit,engine,coda,fee);store.FitEngine(fit,engine,coda,fee);Check(store.Profile.availableCredits==cash-fee&&store.ActiveModelId=="car_coda"&&store.ActiveEngineModelId=="car_bastion","Fitting charges labor once, selects receiver and keeps donor engine identity");Check(store.ActiveWorkshop.gearboxStage==gear&&store.ActiveWorkshop.brakeStage==brakes&&store.ActiveWorkshop.tireStage==tires,"Receiver retains gearbox, brakes and tire quality after engine transplant");Check(EngineInventoryLedger.Find(store.Profile.fleet,displaced).installedCarId==""&&store.Profile.fleet.engines.Count==count,"Displaced receiver engine enters inventory without duplication");var hybrid=WorkshopCatalog.ForBuild(store.ActiveModelId,store.ActiveWorkshop).Resolve(store.ActiveWorkshop);Check(hybrid.carId=="car_coda"&&hybrid.redlineRpm==6200&&hybrid.massKg==1275&&hybrid.ratios.SequenceEqual(WorkshopCatalog.Load("car_coda").car.stock.ratios),"Hybrid powertrain uses V8 rev limits and mass delta with coupe chassis/gearing");var donor=WorkshopCatalog.Load("car_bastion").Resolve(EngineInventoryLedger.Find(store.Profile.fleet,engine).build);Check(hybrid.torque.SequenceEqual(donor.torque)&&Math.Abs(hybrid.PeakKw()-donor.PeakKw())<.001,"Hybrid crank torque/HP is actual donor calibration, not a power multiplier");
  string vector=Buy(store,"car_vector");Parts(store,"gearbox_2");int transferFee=store.EngineTransferFee(coda,vector);int transferCash=store.Profile.availableCredits;string direct=Guid.NewGuid().ToString("N");store.TransferEngine(direct,coda,vector,transferFee);store.TransferEngine(direct,coda,vector,transferFee);Check(!store.HasEngine(coda)&&store.ActiveModelId=="car_vector"&&store.ActiveEngineModelId=="car_bastion"&&store.Profile.availableCredits==transferCash-transferFee,"Direct car-to-car transfer commits both links and fee atomically/idempotently");Reject(()=>store.TransferEngine(direct,vector,bastion,400),"Same request cannot be reused for another swap");string snapshot=File.ReadAllText(file);var failed=new RaceProgressStore(file,route,()=>{throw new IOException("Injected swap failure");});Reject(()=>failed.PullEngine(Guid.NewGuid().ToString("N"),vector),"Injected atomic engine removal failure reports error");Check(File.ReadAllText(file)==snapshot&&new RaceProgressStore(file,route).HasEngine(vector),"Failed engine write preserves prior cash/car/engine links");
  string tempest=Buy(store,"car_tempest");var power=WorkshopCatalog.Load("car_tempest").Resolve(new WorkshopBuild());Check(ChassisTuning.CrankHp(power)>1000&&power.IsTurbo&&power.displayBoostBar>0,"Tempest has real factory twin-turbo torque/spool exceeding1000 crankHP");string finchRequest=Guid.NewGuid().ToString("N");store.BuyReplacement(finchRequest);string finch=store.Profile.fleet.selectedId;Reject(()=>store.EngineTransferFee(tempest,finch),"Compact Finch cannot accept unsupported Tempest V8 package");Reject(()=>store.EngineTransferFee(tempest,vector),"Tempest cross-fit requires gearbox3/brakes2/tires2 support");
  var race=store.BeginDuel(Guid.NewGuid().ToString("N"),"club","pinks");int enginesBefore=store.Profile.fleet.engines.Count;Reject(()=>store.PullEngine(Guid.NewGuid().ToString("N"),finch),"Pending race blocks engine removal");store.SettleDuel(Win(race,route));var won=FleetLedger.Find(store.Profile.fleet,race.opponentId);Check(won.owner=="player"&&EngineInventoryLedger.Find(store.Profile.fleet,won.engineId).owner=="player"&&store.Profile.fleet.engines.Count==enginesBefore,"Pink-slip win transfers fitted engine ownership without copying assemblies");var loaded=new RaceProgressStore(file,route);Check(JsonUtility.ToJson(loaded.Profile.fleet)==JsonUtility.ToJson(store.Profile.fleet),"Complete inventory, transplanted engine links and per-car upgrades replay after reload");var fake=JsonUtility.FromJson<RaceProgress>(File.ReadAllText(file));fake.fleet.cars.First(c=>c.id==coda).engineId=engine;string bad=folder+"/bad.json";File.WriteAllText(bad,JsonUtility.ToJson(fake));Reject(()=>new RaceProgressStore(bad,route),"Forged duplicate engine link cannot override receipt history");fake=JsonUtility.FromJson<RaceProgress>(File.ReadAllText(file));fake.version=10;File.WriteAllText(bad,JsonUtility.ToJson(fake));File.WriteAllText(bad+".bak",File.ReadAllText(file));Reject(()=>new RaceProgressStore(bad,route),"Unknown future10 is rejected without overwriting from older backup");
  string lone=folder+"/lone.json";var only=new RaceProgressStore(lone,route);string original=only.Profile.prototypeCarId;only.PullEngine(Guid.NewGuid().ToString("N"),original);Check(only.Profile.fleet.selectedId==FleetLedger.Loaner&&only.Profile.fleet.cars[0].owner=="player"&&!only.HasEngine(original),"Removing last ready engine keeps chassis ownership and supplies free loaner");Reject(()=>only.BeginDuel(Guid.NewGuid().ToString("N"),"rookie","pinks"),"Loaner cannot be staked after engine removal");Reject(()=>only.PullEngine(Guid.NewGuid().ToString("N"),FleetLedger.Loaner),"Loaner cannot donate a free duplicate engine");Check(File.ReadAllText(old)==bytes,"All swaps/ownership changes leave real v7 source unchanged");GeometryAndRecovery();File.WriteAllLines("Verification/Inventory/rules.txt",checks);
 }catch(Exception e){checks.Add("FAIL "+e);File.WriteAllLines("Verification/Inventory/rules.txt",checks);throw;}}
 static void GeometryAndRecovery(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.position=new Vector3(0,-.5f,300);floor.transform.localScale=new Vector3(100,1,1500);var mode=Physics.simulationMode;Physics.simulationMode=SimulationMode.Script;try{var build=new WorkshopBuild{engineModelId="car_bastion",gearboxStage=3};var car=TrafficWorld.CreateCar("Actual V8 swapped coupe",build,-1,"car_coda");Check(car.PowertrainCarId=="car_coda"&&car.EngineModelId=="car_bastion"&&car.Body.mass==1275&&car.Wheels.Length==4&&Math.Abs(car.wheelBase-2.54f)<.001,"Actual swapped coupe retains frame geometry and four contacts with V8 mass/calibration");UnityEngine.Object.DestroyImmediate(car.gameObject);var ai=TrafficWorld.CreateCar("Bumped AI",new WorkshopBuild(),0);var pilot=ai.gameObject.AddComponent<RoadPilot>();pilot.Car=ai;pilot.Path=Enumerable.Range(0,200).Select(i=>new Vector3(0,.08f,i*3)).ToArray();pilot.CruiseKph=36;pilot.Place(0);for(int i=0;i<120;i++){pilot.Drive(.02f);ai.Tick(.02f);Physics.Simulate(.02f);}ai.Body.AddForce(new Vector3(4200,0,0),ForceMode.Impulse);ai.Body.AddTorque(new Vector3(0,1100,0),ForceMode.Impulse);pilot.NotifyImpact();Check(pilot.Recovering,"Physical side impulse/rotation activates AI rejoin recovery");float start=ai.transform.position.z;for(int i=0;i<900;i++){pilot.Drive(.02f);ai.Tick(.02f);Physics.Simulate(.02f);}Check(ai.transform.position.z>start+20&&Math.Abs(ai.transform.position.x-pilot.Lane)<4&&ai.SpeedKph>10,"Bumped dynamic AI physically reorients, rejoins lane and resumes driving");Check(pilot.Recoveries==0,"Ordinary bump recovery does not teleport AI or skip gates");UnityEngine.Object.DestroyImmediate(ai.gameObject);var tempest=Resources.Load<GameObject>("car_tempest");string[] names={"Front left wheel pivot","Front right wheel pivot","Rear left wheel pivot","Rear right wheel pivot"};for(int i=0;i<4;i++){var p=tempest.transform.Find(names[i]);Check(p!=null&&Math.Abs(p.localPosition.x-(i%2==0?-.84f:.84f))<.002&&Math.Abs(p.localPosition.z-(i<2?1.38f:-1.38f))<.002,"Blender Tempest wheel pivot normalized to correct Unity axle: "+names[i]);}Check(tempest.GetComponentsInChildren<Collider>().Length==0,"Blender Tempest resource remains visual-only before controller installation");}finally{Physics.simulationMode=mode;UnityEngine.Object.DestroyImmediate(floor);}}
 public static void Release(){Run();HarborValeGreybox.Workshop.Editor.AvCameraVerification.Run();HarborValeGreybox.Workshop.Editor.TurboAudioVerification.Run();HarborValeGreybox.Presentation.Editor.CityArtVerification.Release();}
}
}
